SELECT symbol, id, decision, total_score, confidence_score, latest_price, UNIX_TIMESTAMP(generated_at) AS gen_epoch FROM crypto_ai.trade_signal WHERE interval_code='1m' AND ((symbol='EGLDUSDT' AND generated_at BETWEEN FROM_UNIXTIME(1791739501) AND FROM_UNIXTIME(1791741302)) OR (symbol='EGLDUSDT' AND generated_at BETWEEN FROM_UNIXTIME(1791745801) AND FROM_UNIXTIME(1791747602)) OR (symbol='XRPUSDT' AND generated_at BETWEEN FROM_UNIXTIME(1791759901) AND FROM_UNIXTIME(1791761702)) OR (symbol='DOGEUSDT' AND generated_at BETWEEN FROM_UNIXTIME(1791765122) AND FROM_UNIXTIME(1791766923)) OR (symbol='SHIBUSDT' AND generated_at BETWEEN FROM_UNIXTIME(1791774361) AND FROM_UNIXTIME(1791776162)) OR (symbol='ACEUSDT' AND generated_at BETWEEN FROM_UNIXTIME(1791786421) AND FROM_UNIXTIME(1791788222))) ORDER BY symbol, generated_at LIMIT 220;